#nullable enable // autogenerated

using MVZ2.Resources;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        #region Provider
        public void AddTextureProvider(ITexture2DProvider provider)
        {
            textureResolver.AddProvider(provider);
        }
        public void RemoveTextureProvider(ITexture2DProvider provider)
        {
            textureResolver.RemoveProvider(provider);
        }
        #endregion

        public void RegisterTexture2D(NamespaceID key, Texture2D texture2D)
        {
            baseGameTextures.Register(key, texture2D);
        }

        #region 获取Texture2D
        public Texture2D? GetTexture(NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            return baseGameTextures.TryGet(id, out var tex) ? tex : null;
        }
        #endregion

        #region 获取最终贴图
        public Texture2D GetFinalTexture(Texture2D texture2D)
        {
            var id = GetTexture2DID(texture2D);
            return GetFinalTexture(id) ?? texture2D;
        }
        public Texture2D GetFinalTexture(Texture2D texture2D, ResourceContext args)
        {
            var id = GetTexture2DID(texture2D);
            return GetFinalTexture(id, args) ?? texture2D;
        }
        public Texture2D? GetFinalTexture(NamespaceID? id)
        {
            return GetFinalTexture(id, GetResourceContext());
        }
        public Texture2D? GetFinalTexture(NamespaceID? id, ResourceContext context)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            return textureResolver.Resolve(id, context);
        }
        #endregion

        #region SpriteReference
        public NamespaceID? GetTexture2DID(Texture2D texture2D)
        {
            return baseGameTextures.GetKey(texture2D);
        }
        #endregion

        #region 初始化
        private void Init_Textures()
        {
            if (Application.isEditor)
            {
                backgroundTex = GenerateSpriteBackgroundTexture(MAX_BACKGROUND_TEX_WIDTH, MAX_BACKGROUND_TEX_HEIGHT);
            }
            textureResolver.AddProvider(baseGameTextures);
        }
        private void ClearResources_Textures()
        {
            baseGameTextures.Clear();
        }
        #endregion


        [Header("Textures")]
        private Texture2D backgroundTex = null!;
        private TextureResolver textureResolver = new TextureResolver();
        private Texture2DDatabase baseGameTextures = new Texture2DDatabase();
    }
}
